import { render, screen, fireEvent } from '@testing-library/react'
import { describe, it, expect, vi } from 'vitest'

describe('Form action in React 19 JSDOM', () => {
  it('calls action on submit', async () => {
    let actionCalled = false
    let receivedFormData: FormData | null = null

    async function testAction(formData: FormData) {
      actionCalled = true
      receivedFormData = formData
    }

    const { container } = render(
      <form action={testAction}>
        <input name="name" defaultValue="Alice" />
        <button type="submit">Submit</button>
      </form>
    )

    const form = container.querySelector('form')!
    fireEvent.submit(form)

    // In React 19, action is dispatched via microtask / transition
    await vi.waitFor(() => {
      expect(actionCalled).toBe(true)
    })
    expect(receivedFormData?.get('name')).toBe('Alice')
  })
})

