// @vitest-environment jsdom
import { render, screen, fireEvent } from '@testing-library/react'
import { describe, it, expect, vi } from 'vitest'
import ContactForm from './app/ContactForm'

describe('ContactForm', () => {
  it('renders correctly with all inputs and submit button', () => {
    const { container } = render(<ContactForm />)

    expect(screen.getByRole('heading', { name: /contact us/i })).toBeDefined()
    expect(screen.getByLabelText(/name/i)).toBeDefined()
    expect(screen.getByLabelText(/email/i)).toBeDefined()
    expect(screen.getByLabelText(/message/i)).toBeDefined()

    expect(screen.getByPlaceholderText(/name/i)).toBeDefined()
    expect(screen.getByPlaceholderText(/email/i)).toBeDefined()
    expect(screen.getByPlaceholderText(/message/i)).toBeDefined()

    expect(container.querySelector('[name="name"]')).toBeDefined()
    expect(container.querySelector('[name="email"]')).toBeDefined()
    expect(container.querySelector('[name="message"]')).toBeDefined()

    expect(screen.getByRole('button', { name: /submit/i })).toBeDefined()
  })

  it('has an inline server action that validates required fields', async () => {
    const form = ContactForm()
    const action = form.props.action
    expect(typeof action).toBe('function')

    // Test with missing fields
    const emptyFormData = new FormData()
    await expect(action(emptyFormData)).rejects.toThrow(/all fields are required/i)

    // Test missing name
    const missingName = new FormData()
    missingName.set('email', 'test@example.com')
    missingName.set('message', 'Hello')
    await expect(action(missingName)).rejects.toThrow()

    // Test missing email
    const missingEmail = new FormData()
    missingEmail.set('name', 'Alice')
    missingEmail.set('message', 'Hello')
